"""``board-install.sh`` must ship the sources the working tree actually has.

The offline installer embeds a base64 ``.tar.gz`` of the project.  It silently
went stale once (it still carried the ui-v3 sources while the UI had moved on to
v4 and ui-v5 P1–P3), because the blob is generated by hand.  These tests are the
guard:

* the payload is regenerated by ``scripts/build_board_install.py`` and must
  contain exactly the manifest (modules, config, installer, dependencies);
* every shipped byte must match the working tree, so a module added later
  cannot be forgotten;
* the payload keeps out what must never ship (models, media, caches, tests).

A red ``test_payload_content_matches_working_tree`` means: run

    python3 scripts/build_board_install.py

after changing any shipped file.
"""

from __future__ import annotations

import importlib.util
import shutil
import subprocess
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parents[1]
SCRIPT = ROOT / "scripts" / "build_board_install.py"
BOARD_INSTALL = ROOT / "board-install.sh"

#: Modules added after the v3 UI snapshot.  The installer must ship them or the
#: offline install comes up with an older interface than the repository.
P1_P2_P3_MODULES = (
    "src/video_player/browse.py",
    "src/video_player/library.py",
    "src/video_player/probe.py",
    "src/video_player/ui/browse.py",
    "src/video_player/ui/chrome.py",
    "src/video_player/ui/detail_page.py",
    "src/video_player/ui/home_page.py",
    "src/video_player/ui/library_page.py",
    "src/video_player/ui/paint.py",
    "src/video_player/ui/rail.py",
    "src/video_player/ui/style.py",
)

FORBIDDEN_SUFFIXES = (".rknn", ".onnx", ".mp4", ".mkv", ".mov", ".ts", ".pyc")


def _load_builder():
    spec = importlib.util.spec_from_file_location("build_board_install", SCRIPT)
    assert spec is not None and spec.loader is not None
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


@pytest.fixture(scope="module")
def builder():
    return _load_builder()


@pytest.fixture(scope="module")
def payload() -> bytes:
    return _load_builder().payload_of(BOARD_INSTALL.read_bytes())


@pytest.fixture(scope="module")
def payload_files(builder, payload) -> dict[str, bytes]:
    return builder.payload_files(payload)


def test_payload_matches_the_manifest(builder, payload_files) -> None:
    expected = builder.collect_files(ROOT)
    assert expected, "manifest is empty"
    assert sorted(payload_files) == expected


def test_payload_content_matches_working_tree(payload_files) -> None:
    stale = [
        name
        for name, data in payload_files.items()
        if (ROOT / name).is_file() and (ROOT / name).read_bytes() != data
    ]
    assert not stale, (
        "board-install.sh 的离线 payload 已过期，与工作区源码不一致："
        + ", ".join(sorted(stale))
        + "；请运行 python3 scripts/build_board_install.py 重新生成"
    )


def test_payload_is_reproducible(builder, payload) -> None:
    files = builder.collect_files(ROOT)
    rebuilt = builder.encode_payload(builder.build_tarball(ROOT, files))
    assert rebuilt == payload, "payload is not byte-for-byte reproducible"


def test_payload_ships_the_p1_p2_p3_modules(payload_files) -> None:
    missing = [name for name in P1_P2_P3_MODULES if name not in payload_files]
    assert not missing, "离线安装会缺这些新模块：" + ", ".join(missing)


def test_installer_config_and_dependencies_are_shipped(payload_files) -> None:
    for name in ("install.sh", "requirements.txt", "configs/player.example.json"):
        assert name in payload_files, name
    assert payload_files["install.sh"].startswith(b"#!/usr/bin/env bash")


def test_payload_excludes_models_media_and_caches(payload_files) -> None:
    for name in payload_files:
        assert not name.endswith(FORBIDDEN_SUFFIXES), name
        assert not name.startswith(("models/", "tests/", "docs/", ".cache/")), name
        assert "__pycache__" not in name.split("/"), name


def test_payload_paths_are_relative_and_safe(payload_files) -> None:
    for name in payload_files:
        assert not name.startswith("/"), name
        assert ".." not in name.split("/"), name
        assert payload_files[name], f"empty file in payload: {name}"


def test_payload_sources_compile(payload_files) -> None:
    for name, data in payload_files.items():
        if name.endswith(".py"):
            compile(data, name, "exec")


def test_printed_file_count_matches_payload(payload_files) -> None:
    text = BOARD_INSTALL.read_bytes()
    marker = b"source files -> %s\\n' "
    start = text.index(marker) + len(marker)
    end = text.index(b" ", start)
    assert int(text[start:end]) == len(payload_files)


def test_board_install_script_is_valid_bash() -> None:
    bash = shutil.which("bash")
    if bash is None:  # pragma: no cover - bash is a hard requirement elsewhere
        pytest.skip("bash not available")
    proc = subprocess.run(
        [bash, "-n", str(BOARD_INSTALL)], capture_output=True, text=True
    )
    assert proc.returncode == 0, proc.stderr
